# A '-i' vagy hasonló kapcsoló kellhet, ha interaktív módba kell tenni.
proc = subprocess.Popen(
    ['./main'],  
    stdin=subprocess.PIPE,
    stdout=subprocess.PIPE,
    stderr=subprocess.PIPE,
    text=True,
    bufsize=1  # Soronkénti pufferelés
)

# Ez a HTML kód (a Frontend), ami megjelenik a telefonodon
HTML_PAGE = """
<!DOCTYPE html>
<html lang="hu">
<head>
